{
  "packet_id": "H6-T04-3",
  "claim_id": "C052",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C052.component",
    "value": "Several accounts from one organization are not independent confirmation.",
    "scope": "Account evidence clustered within an organization.",
    "provenance": {
      "refs": [
        {
          "source_id": "P032",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P032 explicitly states the within-organization independence limitation."
    }
  },
  "signal_basis": {
    "component_id": "C052.signal_basis",
    "value": "Account-level event sequences and customer reports provide evidence across accounts, including several accounts from the same organization.",
    "scope": "Inspection of account events and customer reports where accounts share organizational membership.",
    "provenance": {
      "refs": [
        {
          "source_id": "P006",
          "role": "SUPPORT"
        },
        {
          "source_id": "P007",
          "role": "SUPPORT"
        },
        {
          "source_id": "P032",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P006 and P007 identify the account-level evidence; P032 supplies the organizational clustering condition."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C052.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No conditional empirical warrant is required for this supported limitation."
    }
  },
  "rationale": "Accounts within one organization can share roster timing, information, procedures and technical conditions. Agreement across those accounts therefore does not by itself establish independent corroboration. The claim licenses this evidential caution within the stated organizational scope.",
  "uncertainty": "The degree of dependence is unspecified; the limitation does not establish that every pair of accounts is necessarily statistically dependent.",
  "anomalies": []
}
